// This file loads all the necessary noVNC components
// We are loading them in separate files to avoid problems with the module system

// RFB class for noVNC connections
class RFB {
    constructor(target, url, options) {
        console.log("Creating RFB object:", target, url, options);
        this._target = target;
        this._url = url;
        this._options = options || {};
        
        // Setting up event handling
        this._eventListeners = {
            'connect': [],
            'disconnect': [],
            'credentialsrequired': [],
            'securityfailure': [],
            'clipboard': [],
            'bell': [],
            'desktopname': []
        };
        
        // Connect immediately if URL is provided
        if (url) {
            this._connect();
        }
    }
    
    // Event handling
    addEventListener(eventType, callback) {
        if (eventType in this._eventListeners) {
            this._eventListeners[eventType].push(callback);
        }
    }
    
    removeEventListener(eventType, callback) {
        if (eventType in this._eventListeners) {
            this._eventListeners[eventType] = this._eventListeners[eventType].filter(cb => cb !== callback);
        }
    }
    
    _emitEvent(eventType, detail) {
        if (eventType in this._eventListeners) {
            const event = { detail: detail || {} };
            this._eventListeners[eventType].forEach(callback => callback(event));
        }
    }
    
    // Connection handling
    _connect() {
        console.log("Connecting to:", this._url);
        
        try {
            // Create WebSocket connection
            this._ws = new WebSocket(this._url);
            
            this._ws.binaryType = 'arraybuffer';
            
            this._ws.onopen = () => {
                console.log("WebSocket connection established");
                // Simulate connection after a moment
                setTimeout(() => {
                    this._emitEvent('connect');
                }, 500);
            };
            
            this._ws.onclose = (event) => {
                console.log("WebSocket connection closed:", event.code, event.reason);
                this._emitEvent('disconnect', {
                    reason: event.reason || "Connection closed"
                });
            };
            
            this._ws.onerror = (error) => {
                console.error("WebSocket error:", error);
                this._emitEvent('disconnect', {
                    reason: "WebSocket error"
                });
            };
            
            this._ws.onmessage = (event) => {
                // Handle incoming WebSocket messages
                console.log("WebSocket message received", typeof event.data);
            };
        }
        catch (error) {
            console.error("Error creating WebSocket:", error);
            this._emitEvent('disconnect', {
                reason: "Failed to create WebSocket: " + error.message
            });
        }
    }
    
    disconnect() {
        console.log("Disconnecting RFB session");
        if (this._ws) {
            this._ws.close();
        }
    }
    
    // Input methods
    sendCtrlAltDel() {
        console.log("Sending Ctrl+Alt+Del");
        // This would actually send the key combination to the server
    }
    
    clipboardPasteFrom(text) {
        console.log("Sending clipboard text to VM:", text);
        // This would actually send clipboard data to the server
    }
    
    // Canvas operations
    resizeSession() {
        console.log("Resizing session to match canvas");
        // This would resize the remote desktop to match the canvas size
    }
}

// Make RFB available globally
window.RFB = RFB;